344→// resolveWorktreeBranch resolves the current branch for a worktree path
345→// by reading the HEAD ref directly from the filesystem
346→func resolveWorktreeBranch(ctx context.Context, worktreePath string) string {
347→	gitPath := filepath.Join(worktreePath, ".git")
348→
349→	fi, err := os.Stat(gitPath)
350→	if err != nil {
351→		return ""
352→	}
353→
354→	var headPath string
355→	if fi.IsDir() {
356→		// Regular repo: .git is a directory
357→		headPath = filepath.Join(gitPath, "HEAD")
358→	} else {
359→		// Worktree: .git is a file containing "gitdir: <path>"
360→		data, err := os.ReadFile(gitPath) //nolint:gosec // path derived from known worktree dir
361→		if err != nil {
362→			return ""
363→		}
364→		content := strings.TrimSpace(string(data))
365→		if !strings.HasPrefix(content, "gitdir: ") {
366→			return ""
367→		}
368→		gitdirPath := strings.TrimPrefix(content, "gitdir: ")
369→		if !filepath.IsAbs(gitdirPath) {
370→			gitdirPath = filepath.Join(worktreePath, gitdirPath)
371→		}
372→		headPath = filepath.Join(gitdirPath, "HEAD")
373→	}
374→
375→	data, err := os.ReadFile(headPath) //nolint:gosec // path constructed from .git/HEAD
376→	if err != nil {
377→		return ""
378→	}
379→
380→	ref := strings.TrimSpace(string(data))
381→
382→	// Symbolic ref: "ref: refs/heads/<branch>"
383→	if strings.HasPrefix(ref, "ref: refs/heads/") {
384→		branch := strings.TrimPrefix(ref, "ref: refs/heads/")
385→		// Reftable ref storage uses "ref: refs/heads/.invalid" as a dummy HEAD stub.
386→		// Fall back to git to resolve the actual branch in that case.
387→		if branch == ".invalid" {
388→			return resolveWorktreeBranchGit(ctx, worktreePath)
389→		}
390→		return branch
391→	}
392→
393→	// Detached HEAD or other ref type
394→	return detachedHEADDisplay
395→}
396→
397→// resolveWorktreeBranchGit resolves the branch name by shelling out to git.
398→// Used as a fallback for reftable ref storage where .git/HEAD is a stub.
399→func resolveWorktreeBranchGit(ctx context.Context, worktreePath string) string {
400→	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
401→	defer cancel()
402→	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--symbolic-full-name", "HEAD")
403→	out, err := cmd.Output()
404→	if err != nil {
405→		return detachedHEADDisplay
406→	}
407→	ref := strings.TrimSpace(string(out))
408→	if strings.HasPrefix(ref, "refs/heads/") {
409→		return strings.TrimPrefix(ref, "refs/heads/")
410→	}
411→	return detachedHEADDisplay
412→}
