795→// cleanupShadowBranchIfUnused deletes a shadow branch if no other active sessions reference it.
796→func (s *ManualCommitStrategy) cleanupShadowBranchIfUnused(ctx context.Context, _ *git.Repository, shadowBranchName, excludeSessionID string) error {
797→	// List all session states to check if any other session uses this shadow branch
798→	allStates, err := s.listAllSessionStates(ctx)
799→	if err != nil {
800→		return fmt.Errorf("failed to list session states: %w", err)
801→	}
802→
803→	for _, state := range allStates {
804→		if state.SessionID == excludeSessionID {
805→			continue
806→		}
807→		otherShadow := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
808→		if otherShadow == shadowBranchName && state.StepCount > 0 {
809→			// Another session still needs this shadow branch
810→			return nil
811→		}
812→	}
813→
814→	// No other sessions need it, delete the shadow branch via CLI
815→	// (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
816→	if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
817→		// Branch already gone is not an error
818→		if errors.Is(err, ErrBranchNotFound) {
819→			return nil
820→		}
821→		return fmt.Errorf("failed to remove shadow branch: %w", err)
822→	}
823→	return nil
